const ALLERGENS=["난류","우유","메밀","땅콩","대두","밀","고등어","게","새우","돼지고기","복숭아","토마토","아황산류","호두","닭고기","쇠고기","오징어","조개류","잣"];
// Fictional fixtures never supply evidence for a branded product.
const TEST_PRODUCTS=ALLERGENS.map((allergen,index)=>({
  id:`test-direct-${index}`,manufacturer:"가상 테스트 상품",isTest:true,
  name:`가상 테스트 상품 · ${allergen} 직접 함유`,
  category:allergen==="우유"?"이온음료":["복숭아","호두"].includes(allergen)?"에너지바":"과자",
  verificationStatus:"FIXTURE",disclosureComplete:true,direct:[allergen],facility:[],
  ingredients:`테스트 설정: ${allergen} 직접 함유`,sourceName:"기능 검증용 가상 데이터 · 실제 상품 아님",checkedAt:null
})).concat([
  {id:"test-facility-wheat",name:"가상 테스트 상품 · 밀 제조환경",category:"과자",direct:[],facility:["밀"],disclosureComplete:true},
  {id:"test-facility-shrimp",name:"가상 테스트 상품 · 새우 제조환경",category:"과자",direct:[],facility:["새우"],disclosureComplete:true},
  {id:"test-unknown",name:"가상 테스트 상품 · 정보 미확인",category:"과자",direct:[],facility:[],disclosureComplete:false}
].map(p=>({...p,isTest:true,manufacturer:"가상 테스트 상품",verificationStatus:p.disclosureComplete?"FIXTURE":"REVIEW_REQUIRED",ingredients:p.disclosureComplete?"직접 함유 기록 없음 · 제조환경만 설정":"표시 정보 미확인으로 설정",sourceName:"기능 검증용 가상 데이터 · 실제 상품 아님",checkedAt:null})));
function catalog(){return state.testMode?TEST_PRODUCTS:PRODUCTS;}
function hasEvidence(p){return p.isTest?p.verificationStatus==="FIXTURE"&&p.disclosureComplete===true:p.verificationStatus==="VERIFIED"&&p.directStatus==="REVIEWED"&&p.facilityStatus==="REVIEWED"&&Boolean(p.sourceUrl&&p.labelUrl&&p.sourceName&&p.checkedAt);}
function matches(p,terms,field){return p[field].filter(a=>terms.includes(a));}
function recommendationCandidates(){return catalog().filter(p=>hasEvidence(p)&&!matches(p,state.foodAllergies,"direct").length&&!matches(p,state.foodAllergies,"facility").length);}
function modeNotice(){return `<div class="mode-panel"><label><input type="checkbox" id="testMode" ${state.testMode?"checked":""}> 가상 테스트 상품 보기</label><p>${state.testMode?"가상 테스트 상품만 표시합니다. 모든 함유·제조환경 정보는 기능 검증용 설정이며 실제 식품이 아닙니다.":"컬리 표시 정보를 확인한 실제 상품입니다. 일부 정보가 미확인인 상품은 추천에서 제외합니다."}</p></div>`;}
// Recognize explicit exclusion phrases, rather than treating every allergen mention as exclusion.
function parseSearch(query){
  const aliases={"밀가루":"밀","달걀":"난류","계란":"난류",...Object.fromEntries(ALLERGENS.map(a=>[a,a]))};
  const atom=Object.keys(aliases).sort((a,b)=>b.length-a.length).join("|");
  const item=`(?:${atom})`;
  const list=`${item}(?:(?:\\s*(?:[·,、/]|및|와|과|하고|랑)\\s*|\\s+)${item})*`;
  const exclusions=[];
  const consume=(phrase)=>{for(const m of phrase.matchAll(new RegExp(atom,"g"))){const a=aliases[m[0]];if(!exclusions.includes(a))exclusions.push(a);}return " ";};
  let rest=query.normalize("NFC").toLowerCase();
  rest=rest.replace(new RegExp(`제외\\s*[:：]?\\s*(${list})`,"g"),consume);
  rest=rest.replace(new RegExp(`(${list})\\s*(?:은|는|을|를|이|가)?\\s*(?:표시\\s*)?(?:제외(?:한|하고|해줘|해\\s*주세요)?|빼고|빼줘|빼\\s*주세요|없는|없어야|없이|안\\s*들어(?:간|있는)?|미포함|불포함|무함유)(?:\\s*것)?`,"g"),consume);
  const category=rest.includes("에너지바")?"에너지바":rest.includes("이온음료")||rest.includes("이온")?"이온음료":rest.includes("과자")?"과자":rest.includes("기타")?"기타":null;
  const text=rest.replace(/에너지바|이온음료|이온|과자|기타|간식|식품|제품|상품|찾아\s*주세요|찾아줘|찾기|추천해\s*주세요|추천해줘|추천|검색|보여줘|전체/g," ").replace(/[·,.:：!?]/g," ").trim();
  return {category,exclusions,text};
}
function searchProducts(query){const parsed=parseSearch(query);const items=catalog().filter(p=>(!parsed.category||p.category===parsed.category)&&(!parsed.text||`${p.name} ${p.manufacturer}`.toLowerCase().includes(parsed.text))&&!matches(p,parsed.exclusions,"direct").length&&!matches(p,parsed.exclusions,"facility").length);return {...parsed,items};}
const ICONS={home:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11.5 12 4l9 7.5"/><path d="M5.5 10.5V20h13v-9.5M9.5 20v-6h5v6"/></svg>',search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg>',card:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 9h18M7 14h4"/></svg>',user:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4.5 20c.8-4 3.3-6 7.5-6s6.7 2 7.5 6"/></svg>'};
const STORAGE_KEY="meogeodoDwaePrototypeV3";
const defaultState={loggedIn:true,account:{displayName:"현정",email:"demo@local.example"},foodAllergies:["밀","복숭아"],drugReactions:[{id:"d1",drugNameOrIngredient:"나프록센",symptom:"복용 후 두드러기",reactionType:"UNKNOWN"}],searchQuery:"밀가루 안 들어간 간식 찾아줘",category:"전체",profileTab:"food",selectedProductId:"p01",testMode:false,detailFrom:"all-products"};
function readState(){let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}");}catch{}const next={...structuredClone(defaultState),...(saved&&typeof saved==="object"?saved:{})};next.foodAllergies=Array.isArray(next.foodAllergies)?[...new Set(next.foodAllergies.filter(a=>ALLERGENS.includes(a)))]:[...defaultState.foodAllergies];next.testMode=next.testMode===true;return next;}
let state=readState();const app=document.querySelector("#app");
function saveState(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{toast("이 브라우저에 저장하지 못했습니다. 저장소 설정을 확인해 주세요.");return false;}}function route(){return(location.hash||"#home").slice(1).split("?")[0]}function go(to){if(route()===to)render();else location.hash=to}function esc(value=""){return String(value).replace(/[&<>'"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[ch]))}
function toast(message){const el=document.querySelector("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2200)}
function reactionLabel(type){return({ALLERGY:"알레르기",ADVERSE_REACTION:"이상반응",UNKNOWN:"잘 모름"})[type]||"잘 모름"}
function productStatus(product){if(!hasEvidence(product))return{text:"정보 미확인",cls:"unknown",reason:product.isTest?"미확인 상태를 재현한 가상 테스트 상품입니다. 제외 조건 충족 여부를 확인할 수 없어 추천에서 제외합니다.":`${product.unknownReason||"출처·확인일이 미확인으로 제외 조건 충족 여부를 확인할 수 없습니다."} 추천에서 제외합니다.`};const direct=matches(product,state.foodAllergies,"direct");const facility=matches(product,state.foodAllergies,"facility");if(direct.length)return{text:"직접 함유 표시",cls:"danger",reason:`저장 항목(${direct.join(", ")})의 직접 함유 기록입니다.${facility.length?` 제조환경 기록: ${facility.join(", ")}.`:""} 추천에서 제외합니다.`};if(facility.length)return{text:"제조환경 경고",cls:"warn",reason:`저장 항목(${facility.join(", ")})의 제조환경 기록입니다. 추천에서 제외하며 섭취 가능 판정을 제공하지 않습니다.`};return{text:"표시상 관련 정보 없음",cls:"neutral",reason:state.foodAllergies.length?"저장 항목과 일치하는 직접 함유·제조환경 기록이 없습니다. 섭취 가능이나 무함유 인증을 뜻하지 않습니다.":"저장한 알레르기 항목이 없습니다. 개인화 비교 기준을 먼저 등록해 주세요."}}
function productCard(product,options={}){const s=productStatus(product);return`<button class="product" data-product="${product.id}"><span>${options.compact===true&&product.isTest?"":`<small class="rec-brand">${esc(product.manufacturer||"시안 데이터")}</small>`}<h3>${esc(product.name)}</h3><span class="badge ${s.cls}">${s.text}</span>${options.compact===true?"":`<p>${esc(s.reason)}</p>`}</span><span class="chev">›</span></button>`}
function titleBlock(title,subtitle,back="home"){return`<div class="screen-title"><button class="back" data-go="${back}" aria-label="이전 화면">‹</button><div><h1>${title}</h1><p>${subtitle}</p></div></div>`}
function localNotice(){return`<div class="notice"><span class="notice-icon">i</span><span><strong>프로토타입 저장 안내</strong><br>입력 정보는 이 브라우저의 기기 저장소에만 저장되며 서버로 전송하거나 제3자에게 제공하지 않습니다.</span></div>`}
const screens={login:{code:"SCR-AUTH-001",nav:null,render:renderLogin},signup:{code:"SCR-SIGNUP-001",nav:null,render:renderSignup},home:{code:"SCR-HOME-001",nav:"home",render:renderHome},recommendations:{code:"SCR-RECO-001",nav:"home",render:renderRecommendations},"all-products":{code:"SCR-PROD-001",nav:"all-products",render:renderAllProducts},results:{code:"SCR-SRCH-001",nav:"all-products",render:renderResults},detail:{code:"SCR-PROD-002",nav:"all-products",render:renderDetail},profile:{code:"SCR-MY-001",nav:"profile",render:renderProfile},card:{code:"SCR-CARD-001",nav:"card",render:renderCard},privacy:{code:"SCR-PRIV-001",nav:"profile",render:renderPrivacy}};
function render(){const key=screens[route()]?route():"home";const screen=screens[key];document.querySelector("#screenCode").textContent=key==="profile"&&state.profileTab==="drug"?"SCR-MY-002":screen.code;const auth=document.querySelector("#authAction");auth.textContent=state.loggedIn?`${state.account.displayName}님 ▾`:"로그인";auth.dataset.go=state.loggedIn?"profile":"login";auth.dataset.action="";document.querySelectorAll("[data-nav]").forEach(btn=>btn.classList.toggle("active",btn.dataset.nav===screen.nav));app.innerHTML=screen.render();app.scrollTop=0;app.focus({preventScroll:true})}
function renderLogin(){return`<div class="stack">${titleBlock("로그인","브라우저 체험 계정으로 개인화 흐름을 확인합니다.","home")}<form class="card stack" id="loginForm"><div class="field"><label for="loginEmail">이메일</label><input id="loginEmail" name="email" type="email" autocomplete="off" value="${esc(state.account.email)}" required></div><div class="field"><label for="loginPassword">비밀번호</label><input id="loginPassword" name="password" type="password" value="demo1234" required minlength="6"><small>입력값은 서버로 보내지 않으며 실제 인증에 사용되지 않습니다.</small></div><button class="primary wide" type="submit">체험 계정으로 로그인</button><button class="secondary wide" type="button" data-go="signup">회원가입 화면 보기</button></form>${localNotice()}</div>`}
function renderSignup(){return`<div class="stack">${titleBlock("회원가입","현재 브라우저에서만 사용하는 체험 계정을 만듭니다.","login")}<div class="notice"><span class="notice-icon">!</span><span><strong>실제 회원가입이 아닙니다.</strong><br>이메일·비밀번호는 서버에 저장되지 않으며, 운영 버전에서는 외부 OIDC/OAuth 인증으로 전환할 설계입니다.</span></div><form class="card stack" id="signupForm"><div class="field"><label for="signupName">이름 또는 별칭</label><input id="signupName" name="displayName" value="이현정" required maxlength="30"></div><div class="field"><label for="signupEmail">이메일</label><input id="signupEmail" name="email" type="email" placeholder="example@email.com" required></div><div class="field"><label for="signupPassword">체험용 비밀번호</label><input id="signupPassword" name="password" type="password" minlength="6" placeholder="6자 이상" required></div><label class="notice"><input name="localConsent" type="checkbox" required><span>현재 브라우저 기기 저장소에 체험 정보를 저장하는 데 동의합니다.</span></label><button class="primary wide" type="submit">브라우저 체험 계정 만들기</button></form></div>`}
function renderHome(){
  const products=catalog();const rec=recommendationCandidates();
  const unknown=products.filter(p=>!hasEvidence(p)).length;
  const direct=products.filter(p=>hasEvidence(p)&&matches(p,state.foodAllergies,"direct").length).length;
  const facility=products.filter(p=>hasEvidence(p)&&!matches(p,state.foodAllergies,"direct").length&&matches(p,state.foodAllergies,"facility").length).length;
  const recRows=rec.length?rec.slice(0,3).map(p=>productCard(p,{compact:true})).join(""):`<div class="empty"><h3>추천 후보가 없습니다</h3><p>직접 함유·제조환경 경고·정보 미확인 상품을 제외한 결과입니다.</p><button class="secondary" data-go="profile">저장 항목 확인</button></div>`;
  return `<div class="stack"><div><p class="eyebrow">내 알레르기: ${esc(state.foodAllergies.join(" · ")||"미등록")}</p><h1>오늘 먹을 간식,<br>표시부터 확인해보세요.</h1></div>${modeNotice()}${searchForm()}<div class="chips"><button class="chip" data-query="밀 표시 없는 에너지바">밀 표시 없는 에너지바</button><button class="chip" data-query="복숭아 표시 없는 과자">복숭아 표시 없는 과자</button><button class="chip" data-query="밀·새우 없는 과자">밀·새우 없는 과자</button></div>${state.loggedIn?`<section class="recommend-panel" aria-label="개인화 추천" aria-live="polite"><div class="recommend-head"><h3>내 알레르기 기준 추천 후보</h3><button class="link-button" data-go="profile">정보 수정</button></div><p>${esc(state.foodAllergies.join(" · ")||"저장 항목 없음")} 기준 · 추천 후보 <strong data-rec-count>${rec.length}</strong>개${state.testMode?" · 가상 테스트 상품":""}</p>${rec.length?recommendationNotice():""}<div class="rec-list">${recRows}</div>${rec.length?`<button class="secondary wide recommendation-all" data-go="recommendations">전체 보기 · ${rec.length}개</button>`:""}<div class="recommend-foot">${products.length}개 중 직접 함유 ${direct}개 · 제조환경 경고 ${facility}개 · 정보 미확인 ${unknown}개 제외</div></section>`:`<div class="card empty"><h3>개인화 추천은 로그인 후 확인</h3><p>브라우저 체험 계정에 저장한 항목을 기준으로 표시를 비교합니다.</p><button class="primary" data-go="login">로그인</button></div>`}<button class="secondary wide" data-go="all-products">${state.testMode?"가상 테스트 상품 전체 보기":"전체 식품 데이터 보기"} · ${products.length}개</button></div>`;
}
function recommendationNotice(){return `<p class="recommendation-notice">${state.foodAllergies.length?"저장 항목과 일치하는 직접 함유·제조환경 기록이 없는 후보입니다.":"저장한 알레르기가 없습니다. 개인화 기준을 먼저 등록해 주세요."} 섭취 가능이나 무함유 인증을 뜻하지 않습니다.</p>`;}
function renderRecommendations(){
  if(!state.loggedIn)return renderHome();
  const rec=recommendationCandidates();
  return `<div class="stack">${titleBlock("알레르기 기준 추천 후보","저장한 기준으로 고른 전체 후보를 확인하세요.","home")}${modeNotice()}<div class="row between"><span class="count-note">${esc(state.foodAllergies.join(" · ")||"저장 항목 없음")} 기준 · 전체 <strong data-rec-count>${rec.length}</strong>개</span><button class="link-button" data-go="profile">정보 수정</button></div>${rec.length?recommendationNotice():""}<div class="rec-list">${rec.length?rec.map(p=>productCard(p,{compact:true})).join(""):`<div class="card empty"><h3>추천 후보가 없습니다</h3><p>직접 함유·제조환경 경고·정보 미확인 상품을 제외한 결과입니다.</p><button class="secondary" data-go="profile">저장 항목 확인</button></div>`}</div></div>`;
}

function searchForm(){return `<form class="search-box" id="searchForm"><input name="q" aria-label="제품 검색" value="${esc(state.searchQuery)}" placeholder="예: 밀·새우 없는 과자"><button>찾기</button></form>`;}
function renderAllProducts(){
  const products=catalog();const cats=["전체","과자","에너지바","이온음료","기타"];
  const counts=Object.fromEntries(cats.slice(1).map(c=>[c,products.filter(p=>p.category===c).length]));
  const shown=products.filter(p=>state.category==="전체"||p.category===state.category);
  return `<div class="stack">${titleBlock("전체 식품 데이터","등록된 목록과 표시 기록을 확인합니다.","home")}${modeNotice()}<div class="stats"><div class="stat"><strong>${products.length}</strong><span>${state.testMode?"가상 테스트 상품":"실제 상품"}</span></div><div class="stat"><strong>${products.filter(p=>!hasEvidence(p)).length}</strong><span>정보 미확인</span></div></div><div class="card"><h3>카테고리별 상품 수</h3><div class="chips">${Object.entries(counts).map(([c,n])=>`<span class="chip">${c} ${n}</span>`).join("")}</div></div><div class="chips" role="group" aria-label="카테고리 필터">${cats.map(c=>`<button class="chip ${state.category===c?"active":""}" data-category="${c}">${c}</button>`).join("")}</div><span class="count-note">${shown.length}개 표시</span><div class="product-list">${shown.length?shown.map(productCard).join(""):`<div class="card empty"><h3>이 카테고리에 상품이 없습니다</h3><button class="secondary" data-category="전체">전체 보기</button></div>`}</div><div class="notice"><span class="notice-icon">i</span><span>${state.testMode?"명확히 가상으로 표시한 기능 검증 데이터입니다. 실제 브랜드 성분 정보가 아닙니다.":"컬리 상품정보 이미지의 표시 기록입니다. 상세에서 맛·중량·출처와 확인일을 확인하세요. 빈 기록은 무함유를 의미하지 않습니다."}</span></div></div>`;
}
function renderResults(){
  const result=searchProducts(state.searchQuery);
  const compared=result.items.filter(p=>hasEvidence(p)&&!matches(p,state.foodAllergies,"direct").length&&!matches(p,state.foodAllergies,"facility").length);
  const warnings=result.items.filter(p=>hasEvidence(p)&&(matches(p,state.foodAllergies,"direct").length||matches(p,state.foodAllergies,"facility").length));
  const unknown=result.items.filter(p=>!hasEvidence(p));
  const group=(title,items,kind)=>items.length?`<section class="stack result-group" data-result-group="${kind}"><h2>${title} · ${items.length}개</h2>${kind==="unknown"?"<p>아래 상품은 제외 조건 충족 여부를 확인할 수 없습니다. 추천 후보가 아닙니다.</p>":""}<div class="product-list">${items.map(productCard).join("")}</div></section>`:"";
  return `<div class="stack">${titleBlock("검색 결과","검색어의 제외 조건을 직접 함유·제조환경 기록 모두에 적용합니다.","home")}${modeNotice()}${searchForm()}<div class="card tint"><h3>검색어에서 이렇게 이해했어요</h3><div class="chips">${result.category?`<span class="chip selected">${result.category}</span>`:""}${result.exclusions.map(t=>`<span class="chip selected">제외: ${esc(t)}</span>`).join("")||'<span class="count-note">특정 제외 항목 없음</span>'}${result.text?`<span class="chip selected">이름: ${esc(result.text)}</span>`:""}</div><p>JavaScript 키워드 매핑입니다. 실제 LLM 연동이 아닙니다.</p><p>저장 항목: ${esc(state.foodAllergies.join(" · ")||"없음")} · 관련 상품은 아래 경고 영역에 표시합니다.</p></div><p class="count-note" data-search-count>표시 기록 비교 ${compared.length}개 · 저장 항목 경고 ${warnings.length}개 · 정보 미확인 ${unknown.length}개</p>${group("표시 기록 비교 결과",compared,"compared")}${group("저장 항목 관련 경고",warnings,"warnings")}${group("정보 미확인",unknown,"unknown")}${result.items.length?"":`<div class="card empty"><h3>검색 결과가 없습니다</h3><p>상품 이름·카테고리·제외 항목을 바꿔 보세요.</p><button class="secondary" data-go="home">검색 조건 바꾸기</button></div>`}<div class="notice"><span class="notice-icon">!</span><span>검색 결과는 섭취 가능 판정이 아닙니다. 제조환경 경고·정보 미확인 상품은 추천하지 않습니다.${state.testMode?" 모든 상품은 가상 테스트 데이터입니다.":" 현재 포장지를 재확인하세요."}</span></div></div>`;
}
function renderDetail(){
  const p=catalog().find(x=>x.id===state.selectedProductId)||catalog()[0];const s=productStatus(p);
  const row=(label,value)=>`<div class="data-row"><span>${label}</span><strong>${esc(value)}</strong></div>`;
  const disclosure=(field)=>{
    if(p.isTest)return p[field].length?`${p[field].join(", ")} (가상 설정)`:hasEvidence(p)?"가상 설정상 기록 없음":"미확인 · 빈 기록으로 무함유를 판단할 수 없음";
    return p[`${field}Status`]==="REVIEWED"?p[`${field}Label`]||"출처 표시 문구 없음 · 무함유 인증 아님":"미확인 · 출처에 문구가 없어 판단할 수 없음";
  };
  const sources=p.isTest?row("근거",p.sourceName):`<div class="card stack"><h3>확인한 출처</h3><p>${esc(p.sourceName)}</p><p>${esc(p.sourceScope)}</p><a class="source-link" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">컬리 상품 상세 열기 ↗</a><a class="source-link" href="${esc(p.labelUrl)}" target="_blank" rel="noopener noreferrer">원본 표시 정보 이미지 열기 ↗</a><p class="count-note">확인일은 페이지를 읽은 날짜이며 현재 판매분의 포장지를 확인한 날짜가 아닙니다.</p></div>`;
  return `<div class="stack">${titleBlock("제품 근거·상세",p.isTest?"가상 테스트 상품 · 실제 식품이 아닙니다.":"출처 이미지에 표시된 정보를 옮겼습니다. 현재 포장지도 확인해 주세요.",["home","recommendations","results","all-products"].includes(state.detailFrom)?state.detailFrom:"all-products")}<div class="detail-hero"><small>${esc(p.manufacturer)} · ${esc(p.category)}</small><h2>${esc(p.name)}</h2><span class="badge ${s.cls}">${s.text}</span></div><div class="card"><h3>분류 근거</h3><p>${esc(s.reason)}</p></div><div class="card data-rows">${row(p.isTest?"원재료 테스트 설정":p.ingredientsIsSummary?"원재료 요약":"원재료 표시",p.ingredients)}${row("직접 함유 표시",disclosure("direct"))}${row("제조환경 문구",disclosure("facility"))}${row(p.isTest?"실제 상품 확인일":"출처 확인일",p.isTest?"해당 없음 · 가상 테스트 상품":p.checkedAt||"미확인")}</div>${sources}${!p.isTest&&p.ingredientsIsSummary?'<p class="count-note">원재료는 요약이며 전체 목록은 원본 이미지를 확인하세요.</p>':""}<div class="notice"><span class="notice-icon">!</span><span>${p.isTest?"테스트 설정은 조건 변경에 따른 기능 검증만을 위한 데이터입니다. 실제 브랜드 상품의 성분을 나타내지 않습니다.":"제품 정보와 제조공정은 바뀔 수 있습니다. 현재 포장지와 제조사 최신 안내를 다시 확인하세요."}</span></div></div>`;
}
function renderProfile(){const food=`<form class="stack" id="foodForm"><div><h3>식품 알레르기 관리</h3><p>제공된 프로젝트의 19개 항목 중 해당 항목을 선택합니다.</p></div><div class="allergen-grid">${ALLERGENS.map(a=>`<label><input type="checkbox" name="allergen" value="${a}" ${state.foodAllergies.includes(a)?"checked":""}><span>${a}</span></label>`).join("")}</div><button class="primary wide">선택 항목 저장</button><p class="saved-summary" role="status">저장한 항목: ${esc(state.foodAllergies.join(" · ")||"없음")}<br>현재 ${state.testMode?"가상 테스트":"실제 상품"} 목록의 추천 후보 ${recommendationCandidates().length}개</p></form>`;const drug=`<div class="stack"><div><h3>약물 알레르기·이상반응 기록</h3><p>의료진에게 보여주기 위한 사용자 입력 기록이며 진단서가 아닙니다.</p></div>${state.drugReactions.length?state.drugReactions.map(d=>`<div class="reaction-item row between"><span><strong>${esc(d.drugNameOrIngredient)}</strong><small>${reactionLabel(d.reactionType)}${d.symptom?` · ${esc(d.symptom)}`:""}</small></span><button class="link-button" data-delete-reaction="${d.id}">삭제</button></div>`).join(""):'<div class="empty"><p>기록이 없습니다.</p></div>'}<form class="card stack" id="drugForm"><div class="field"><label for="drugName">약물명 또는 주성분</label><input id="drugName" name="drugNameOrIngredient" placeholder="예: 페니실린" required></div><div class="field"><label for="symptom">경험한 증상 (선택)</label><input id="symptom" name="symptom" placeholder="예: 두드러기"></div><div class="field"><label for="reactionType">구분</label><select id="reactionType" name="reactionType"><option value="ALLERGY">알레르기</option><option value="ADVERSE_REACTION">이상반응</option><option value="UNKNOWN" selected>잘 모름</option></select></div><button class="primary wide">기록 추가</button></form><div class="notice"><span class="notice-icon">!</span><span>약물 추천, 대체약 추천, 복용 가능 여부 판단은 제공하지 않습니다.</span></div></div>`;return`<div class="stack"><div class="row between"><div><h1>내 정보</h1><p>검색에 적용할 항목과 보여줄 기록을 관리합니다.</p></div><button class="link-button" data-go="privacy">개인정보 처리 안내</button></div>${localNotice()}<div class="segmented"><button class="${state.profileTab==="food"?"active":""}" data-tab="food">식품 알레르기</button><button class="${state.profileTab==="drug"?"active":""}" data-tab="drug">약물·이상반응</button></div>${state.profileTab==="food"?food:drug}<button class="secondary wide" data-action="logout">체험 계정 로그아웃</button></div>`}
function renderCard(){return`<div class="stack"><div><h1>알레르기 카드</h1><p>병원이나 식당에서 참고용으로 바로 보여주세요.</p></div><div class="pass"><span class="mini">MY ALLERGY CARD · 사용자 입력 정보</span><h2>${esc(state.account.displayName)}</h2><p>현재 브라우저에 저장된 참고 기록</p><div class="pass-section"><span>식품 알레르기</span><strong>${state.foodAllergies.join(", ")||"입력 없음"}</strong></div><div class="pass-section"><span>약물 알레르기·이상반응</span>${state.drugReactions.length?state.drugReactions.map(d=>`<strong>${esc(d.drugNameOrIngredient)} · ${reactionLabel(d.reactionType)}${d.symptom?`<br><small>${esc(d.symptom)}</small>`:""}</strong>`).join("<br>"):"입력 없음"}</div><div class="pass-section"><span>안내</span><strong>본인이 직접 입력한 참고 정보이며 공식 의료기록이나 진단서가 아닙니다.</strong></div></div><button class="primary wide" data-action="enlarge-card">크게 보여주기</button><button class="secondary wide" data-go="profile">정보 수정</button><div class="notice"><span class="notice-icon">i</span><span>친구 추가·자동 공유는 MVP에 포함하지 않습니다. 이 화면은 기기 소유자가 직접 보여주는 용도입니다.</span></div></div>`}
function renderPrivacy(){return`<div class="stack">${titleBlock("개인정보 처리 안내","프로토타입과 향후 운영 서비스의 범위를 구분합니다.","profile")}<div class="card"><h2>현재 프로토타입</h2><ul class="privacy-list"><li>입력 정보는 이 브라우저의 기기 저장소(localStorage)에만 저장됩니다.</li><li>서버 전송 및 제3자 제공이 없습니다.</li><li>브라우저 데이터 삭제 시 정보가 함께 삭제될 수 있습니다.</li><li>공용 기기에서는 민감한 건강 정보 입력을 권장하지 않습니다.</li></ul></div><div class="card tint"><h2>운영 서비스 전환 시 필요</h2><ul class="privacy-list"><li>개인정보 처리방침 및 민감정보 수집·이용 동의</li><li>최소 수집과 목적 제한</li><li>전송·저장 암호화</li><li>OIDC/OAuth 본인 인증과 접근 통제</li><li>보관 기간 및 안전한 파기 정책</li><li>접근·공유 이력 관리</li></ul></div><div class="card"><h2>향후 공유 기능 원칙</h2><ul class="privacy-list"><li>친구 검색과 자동 공유 금지</li><li>사용자가 직접 고른 정보만 공유</li><li>약물 이상반응은 기본 공유 대상에서 제외</li><li>일회성 또는 만료되는 QR·링크</li><li>즉시 철회와 열람 이력 제공</li><li>기본값은 “공유 안 함”</li></ul></div><button class="ghost wide" data-action="clear-local">이 브라우저의 체험 정보 초기화</button></div>`}
function registerWebMcpTools(){
  const context=typeof document==="undefined"?undefined:document.modelContext;
  if(!context?.registerTool)return;
  try{
    void Promise.resolve(context.registerTool({
      name:"set_food_allergies",
      title:"식품 알레르기 항목 저장",
      description:"프로토타입의 개인화 기준으로 사용할 식품 알레르기 항목을 현재 브라우저에 저장하고 화면을 갱신합니다.",
      inputSchema:{type:"object",properties:{allergens:{type:"array",items:{type:"string",enum:ALLERGENS},uniqueItems:true}},required:["allergens"],additionalProperties:false},
      annotations:{readOnlyHint:false,untrustedContentHint:false},
      execute(input){
        if(!input||typeof input!=="object"||!Array.isArray(input.allergens))throw new TypeError("allergens 배열이 필요합니다.");
        const allergens=input.allergens.map(String);
        if(new Set(allergens).size!==allergens.length||allergens.some(item=>!ALLERGENS.includes(item)))throw new TypeError("지원하는 알레르기 항목만 중복 없이 입력해 주세요.");
        state.foodAllergies=allergens;
        if(!saveState())throw new Error("브라우저 저장 실패");
        render();
        return{foodAllergies:[...state.foodAllergies],storage:"localStorage",serverTransmission:false};
      }
    })).catch(error=>console.warn("WebMCP tool registration failed",error));
  }catch(error){console.warn("WebMCP tool registration failed",error)}
}
document.addEventListener("click",event=>{const goButton=event.target.closest("[data-go]");if(goButton){event.preventDefault();go(goButton.dataset.go);return}const auth=event.target.closest("[data-action='logout']");if(auth){state.loggedIn=false;saveState();toast("브라우저 체험 계정에서 로그아웃했습니다.");go("home");return}const q=event.target.closest("[data-query]");if(q){state.searchQuery=q.dataset.query;if(saveState())go("results");return}const category=event.target.closest("[data-category]");if(category){state.category=category.dataset.category;saveState();render();return}const product=event.target.closest("[data-product]");if(product){state.detailFrom=route();state.selectedProductId=product.dataset.product;saveState();go("detail");return}const tab=event.target.closest("[data-tab]");if(tab){state.profileTab=tab.dataset.tab;saveState();render();return}const del=event.target.closest("[data-delete-reaction]");if(del){state.drugReactions=state.drugReactions.filter(d=>d.id!==del.dataset.deleteReaction);saveState();render();toast("기록을 삭제했습니다.");return}if(event.target.closest("[data-source-link]")){event.preventDefault();document.querySelector("#prototype-source")?.scrollIntoView({behavior:"smooth",block:"center"});return}if(event.target.closest("[data-action='enlarge-card']")){toast("제시용 카드입니다. 공식 의료기록이 아닙니다.");return}if(event.target.closest("[data-action='clear-local']")){localStorage.removeItem(STORAGE_KEY);state={...structuredClone(defaultState),loggedIn:false,foodAllergies:[],drugReactions:[]};toast("이 브라우저의 체험 정보를 초기화했습니다.");render()}});
document.addEventListener("submit",event=>{event.preventDefault();const form=event.target;const data=new FormData(form);if(form.id==="searchForm"){state.searchQuery=String(data.get("q")||"").trim();if(!state.searchQuery)return toast("찾고 싶은 식품이나 제외 항목을 입력해 주세요.");if(saveState())go("results")}if(form.id==="loginForm"){state.loggedIn=true;state.account.email=String(data.get("email")||state.account.email);saveState();toast("브라우저 체험 계정으로 로그인했습니다.");go("home")}if(form.id==="signupForm"){state.loggedIn=true;state.account={displayName:String(data.get("displayName")||"체험 사용자"),email:String(data.get("email")||"")};saveState();toast("이 브라우저에만 체험 계정을 만들었습니다.");go("profile")}if(form.id==="foodForm"){state.foodAllergies=data.getAll("allergen").map(String);if(saveState()){toast("저장했습니다. 추천 후보와 검색 경고를 갱신했습니다.");render()}}if(form.id==="drugForm"){state.drugReactions.push({id:`d${Date.now()}`,drugNameOrIngredient:String(data.get("drugNameOrIngredient")||""),symptom:String(data.get("symptom")||""),reactionType:String(data.get("reactionType")||"UNKNOWN")});saveState();toast("약물 이상반응 기록을 추가했습니다.");render()}});
document.addEventListener("change",event=>{if(event.target.id!=="testMode")return;state.testMode=event.target.checked;state.selectedProductId=catalog()[0].id;if(saveState()){render();toast(state.testMode?"가상 테스트 상품만 표시합니다.":"실제 상품 목록으로 돌아왔습니다.");}});
window.addEventListener("hashchange",render);document.querySelectorAll("[data-icon]").forEach(el=>el.innerHTML=ICONS[el.dataset.icon]);render();registerWebMcpTools();
